let mySettings=null;
async function openMySettings(){try{mySettings=await api('settings-load');drawMySettings();}catch(e){toast(e.message);}}
function drawMySettings(){const d=mySettings,p=d.profile||{},jobs=(d.jobs||[]).filter(j=>j.active||j.id===p.job_title_id);show(`<h2>Minhas configurações</h2><p>Seus dados pessoais e de acesso.</p>${d.photo?`<img src="${esc(d.photo)}" alt="Sua foto" width="72" height="72" style="object-fit:cover;border-radius:50%;margin:16px 0">`:''}${!d.ready?'<div class="notice">O cadastro pessoal aguarda a execução do SQL de configurações no Supabase. A alteração de senha já está disponível.</div>':''}<form><div class="formgrid">${field('full_name','Nome completo',p.full_name||user().name,'text','required maxlength="180"')}${field('cpf','CPF',p.cpf||'','text','maxlength="14" inputmode="numeric"')}${field('contact_email','E-mail de contato',p.contact_email||'','email','maxlength="254"')}${field('phone','Telefone / WhatsApp',p.phone||'','tel','maxlength="30"')}${select('job_title_id','Cargo',[['','Não informado'],...jobs.map(j=>[j.id,j.name+(j.active?'':' (inativo)')])],p.job_title_id||'')}</div><h3>Dados para recebimento</h3><div class="formgrid">${[['bank_name','Banco'],['bank_agency','Agência'],['bank_account','Conta com dígito'],['bank_holder','Titular da conta'],['pix_key','Chave Pix']].map(([key,label])=>field(key,label,p[key]||'','text','maxlength="180"')).join('')}</div><p class="small">O cargo descreve sua função. As empresas e permissões são definidas pelo administrador.</p>${d.ready?actions():''}</form>${d.ready?'<h3>Foto de perfil</h3><label>JPG ou PNG · até 2 MB<input type="file" accept="image/jpeg,image/png" onchange="uploadMyPhoto(this.files[0])"></label>':''}<h3>Acesso</h3><p>E-mail de acesso: <strong>${esc(d.loginEmail||user().email)}</strong></p><p class="small">O e-mail de contato não altera o login. Para trocar o e-mail de acesso, solicite ao administrador.</p><div class="actions">${isAdmin()?btn('Gerenciar cargos','openJobSettings()',true):''}${btn('Alterar senha','openPasswordSettings()',true)}${btn('Fechar',"document.getElementById('modal').close()",true)}</div>`,async f=>{if(!d.ready)throw Error('Execute o SQL de configurações primeiro.');await api('settings-save',{profile:Object.fromEntries(['full_name','cpf','contact_email','phone','job_title_id','bank_name','bank_agency','bank_account','bank_holder','pix_key'].map(k=>[k,f.get(k)||'']))});const savedPage=page,savedCompany=company;await loadCloud();page=savedPage;company=savedCompany;render();await openMySettings();toast('Dados pessoais atualizados.');});}
async function uploadMyPhoto(file){if(!file)return;try{if(!['image/jpeg','image/png'].includes(file.type)||file.size>2097152||!file.size)throw Error('Envie JPG ou PNG de até 2 MB.');const upload=await api('photo-begin',{contentType:file.type,size:file.size});const response=await fetch(upload.url,{method:'PUT',headers:{'Content-Type':file.type,'x-upsert':'false'},body:file});if(!response.ok)throw Error('Não foi possível enviar a foto.');await api('photo-finish');await openMySettings();toast('Foto atualizada.');}catch(e){toast(e.message);}}
async function openJobSettings(){if(!isAdmin())return;try{const d=await api('settings-load');if(!d.ready)return toast('Execute o SQL de configurações primeiro.');show(`<h2>Cargos da equipe</h2><p>Disponíveis para seleção nas configurações pessoais.</p><ul>${d.jobs.map(j=>`<li style="margin:12px 0">${esc(j.name)} · ${j.active?'Ativo':'Inativo'} ${btn(j.active?'Desativar':'Ativar',`toggleJob('${actionId(j.id)}',${!j.active})`,true)}</li>`).join('')||'<li>Nenhum cargo cadastrado.</li>'}</ul><form>${field('name','Novo cargo','','text','required minlength="2" maxlength="100"')}${actions()}</form>`,async f=>{await api('job-save',{name:f.get('name')});await openJobSettings();});}catch(e){toast(e.message);}}
async function toggleJob(id,active){const job=mySettings?.jobs?.find(j=>j.id===id);try{const d=await api('settings-load'),j=d.jobs.find(j=>j.id===id);if(!j)throw Error('Cargo não encontrado.');await api('job-save',{id,name:j.name,active});await openJobSettings();}catch(e){toast(e.message);}}
function openPasswordSettings(){show(`<h2>Alterar senha</h2><form>${field('currentPassword','Senha atual','','password','required autocomplete="current-password"')}${field('newPassword','Nova senha','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}${field('confirmPassword','Confirmar nova senha','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<p class="small">Use pelo menos 12 caracteres. A senha é enviada somente ao serviço de autenticação.</p>${actions()}</form>`,async f=>{const password=f.get('newPassword');if(password!==f.get('confirmPassword'))throw Error('As senhas não coincidem.');const session=await authRequest('token?grant_type=password',{email:mySettings?.loginEmail||user().email,password:f.get('currentPassword')});const response=await fetch(CLOUD_URL+'/auth/v1/user',{method:'PUT',headers:{apikey:CLOUD_KEY,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:JSON.stringify({password})});const result=await response.json();if(!response.ok)throw Error(result.msg||result.message||'Não foi possível alterar a senha.');cloudSession=session;localStorage.setItem('comissions-auth-session',JSON.stringify(session));document.getElementById('modal').close();toast('Senha alterada.');});}
